function validate(input) {
  const [{ Employees = [] }] = input;
  const ids = new Set(), managers = new Map();
  for (const [id, name, dep, position] of Employees) {
    if (id === null || name === null || dep === null || position === null) return 'Every employee needs an id, a name, a department and a position.';
    if (ids.has(id)) return `emp_id ${id} appears twice.`;
    ids.add(id);
    managers.set(dep, (managers.get(dep) ?? 0) + (position.toLowerCase() === 'manager' ? 1 : 0));
  }
  for (const [dep, count] of managers) if (count !== 1) return `Department ${dep} must have exactly one Manager.`;
  return null;
}

