function generate(rand, size) {
  const names = ['Michael', 'Lucas', 'Isabella', 'Joseph', 'Aiden', 'Skylar', 'Stella', 'Audrey', 'Nathan', 'Ian', 'Ethan', 'Lee'];
  const roles = ['Consultant', 'Engineer', 'Freelancer', 'Coordinator', 'Supervisor', 'Administrator'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const departments = size === 'small' ? Math.floor(rand() * 4) : 300;
  const maxSize = size === 'small' ? 3 : 10;
  // Increasing department ids with random gaps; each gets a manager plus 0..maxSize-1 other employees.
  const rows = [];
  let dep = 99;
  for (let d = 0; d < departments; d++) {
    dep += 1 + Math.floor(rand() * 4);
    rows.push([dep, 'Manager']);
    const extra = Math.floor(rand() * maxSize);
    // Small sets stay within 8 rows, leaving room for the later departments' managers.
    for (let i = 0; i < extra && (size !== 'small' || rows.length + departments - d - 1 < 8); i++) rows.push([dep, pick(roles)]);
  }
  // Shuffle so managers and departments come in mixed order; employee ids are increasing with gaps, so unique.
  for (let i = rows.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rows[i], rows[j]] = [rows[j], rows[i]]; }
  let id = 0;
  const Employees = rows.map(([dep, position]) => [id += 1 + Math.floor(rand() * 20), pick(names), dep, position]);
  for (let i = Employees.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Employees[i][0], Employees[j][0]] = [Employees[j][0], Employees[i][0]]; }
  return [{ Employees }];
}
